import json, numpy as np
from geo_ref import V
AX={}
def axis(zh):
    if zh in AX: return AX[zh]
    v=V(zh); c=v.mean(0); u,s,vt=np.linalg.svd(v-c); a=vt[0]
    if a[1]>0: a=-a                      # 由上（近端）往下
    pr=(v-c)@a; p0=c+a*pr.min(); p1=c+a*pr.max()
    z=np.array([0,0,1.0]); z=z-a*(z@a); z/=np.linalg.norm(z)
    x=np.cross(a,z);                     # 右手系：a 向下、z 向前 → x 向（左側）外？確保 x 指向 +x
    if x[0]<0: x=-x
    AX[zh]=(p0,p1,z,x); return AX[zh]
def B(zh,t,ant=0.0,lat=0.0):
    p0,p1,z,x=axis(zh); return (p0+(p1-p0)*t+z*ant+x*lat).tolist()
