# 椎管（中線）：各椎骨的前後範圍內 55% 處
def canal(zh,frac=0.55):
    v=V(zh); return [0.0, float(v[:,1].mean()), float(v[:,2].max()-(v[:,2].max()-v[:,2].min())*frac)]
VERT=['寰椎（C1）']+['第%d頸椎（C%d）'%(i,i) for i in range(3,8)]+['第%d胸椎（T%d）'%(i,i) for i in range(1,13)]+['第%d腰椎（L%d）'%(i,i) for i in range(1,3)]
