def C(lv): return canal({'C4':'第4頸椎（C4）','C5':'第5頸椎（C5）','C6':'第6頸椎（C6）','C7':'第7頸椎（C7）','T1':'第1胸椎（T1）','L1':'第1腰椎（L1）','L2':'第2腰椎（L2）','L3':'第3腰椎（L3）','L4':'第4腰椎（L4）','L5':'第5腰椎（L5）'}[lv])
